#include "v32bis_viterbi.h"
#include "v32bis_map.h"
#include "v32bis_trellis.h"
#include <float.h>
#include <string.h>
static int bits_for_rate(int rate){return rate==7200?3:rate==9600?4:rate==12000?5:rate==14400?6:0;}
int v32bis_viterbi_init(struct v32bis_viterbi*v,int rate){int bits=bits_for_rate(rate);if(!v||!bits)return-1;memset(v,0,sizeof *v);v->rate=rate;v->info_bits=bits;for(unsigned s=1;s<8;s++)v->metric[s]=DBL_MAX/4;return 0;}
int v32bis_viterbi_put(struct v32bis_viterbi*v,double i,double q,uint8_t*out){if(!v||!v->info_bits)return-1;double nm[8];uint8_t pred[8]={0},data[8]={0};for(unsigned s=0;s<8;s++)nm[s]=DBL_MAX;unsigned eb=(unsigned)v->info_bits-2,ec=1u<<eb;for(unsigned state=0;state<8;state++)if(v->metric[state]<DBL_MAX/8)for(unsigned y12=0;y12<4;y12++){unsigned ns=v32bis_trellis_next_state(state,y12),subset=v32bis_trellis_subset(state,y12);double branch=DBL_MAX;unsigned bx=0;for(unsigned x=0;x<ec;x++){unsigned label=(subset<<eb)|x;struct v32bis_point p;if(v32bis_map_point(v->rate,label,&p)<0)return-1;double di=i-p.i,dq=q-p.q,d=di*di+dq*dq;if(d<branch){branch=d;bx=x;}}double candidate=v->metric[state]+branch;if(candidate<nm[ns]){nm[ns]=candidate;pred[ns]=(uint8_t)state;data[ns]=(uint8_t)((y12<<eb)|bx);}}unsigned slot=(unsigned)(v->time%V32BIS_TRACEBACK);for(unsigned s=0;s<8;s++){v->metric[s]=nm[s];v->predecessor[slot][s]=pred[s];v->payload[slot][s]=data[s];}v->time++;if(v->time<V32BIS_TRACEBACK)return 0;unsigned state=0;for(unsigned s=1;s<8;s++)if(v->metric[s]<v->metric[state])state=s;for(unsigned back=0;back<V32BIS_TRACEBACK-1;back++){unsigned at=(unsigned)((v->time-1-back)%V32BIS_TRACEBACK);state=v->predecessor[at][state];}unsigned oldest=(unsigned)((v->time-V32BIS_TRACEBACK)%V32BIS_TRACEBACK);if(out)*out=v->payload[oldest][state];return 1;}
